export default function install(app){let root=null,stamp=0;function clear(){++stamp;const all=document.querySelectorAll('section');for(const e of all){if(e.textContent?.includes('KI-Luftbildsichtung')){e.style.display='none';const img=e.querySelector('img');if(img){img.removeAttribute('src');img.style.display='none';}}}for(const svg of document.querySelectorAll('svg')){if(svg.querySelector('path[stroke-dasharray="6 5"]')){const ring=svg.querySelector('path[stroke-dasharray="6 5"]');ring?.setAttribute('d','');for(const line of svg.querySelectorAll('line'))for(const a of ['x1','x2','y1','y2'])line.setAttribute(a,'0');}}}window.addEventListener('esg-clear-request',clear);app.onCleanup(()=>window.removeEventListener('esg-clear-request',clear));}